update public.bg_schrijfregels set regel='Alle Bedrijfsgeheugen/Powerhouse agents gebruiken één canonieke contentlus. Voor Arthur persoonlijk LinkedIn is de standaardlijn het echte AI-native bouwproces: zijn droom bouwen, een concreet bedrijfsprobleem oplossen, laten zien wat er echt gebeurde, wat hij veranderde en wat hij gelooft over de toekomst van AI in bedrijven. Schrijf voor niet-technische ondernemers; interne systeemtaal en technische statusrapportage zijn verboden in publieke copy. Geen geforceerde zakelijke CTA of productpitch. Ontbrekende data nooit verzinnen.', onderbouwing='Persoonlijke kanaalclausule geactualiseerd op expliciete gebruikersinstructie 2026-10-07.', bewijs_n=1, vertrouwen=1.0, status='actief', bron='canonical-brain-contract+user_instruction', bijgewerkt_op=now() where regel_id='canonical-revenue-content-closed-loop-v1';
